import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.wVcpyw2-.js";const g=JSON.parse('{"title":"笔记列表组件（完整手册）","description":"笔记列表组件（完整手册）：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/components/note-list.md","filePath":"features/ui-editor/components/note-list.md","lastUpdated":1785020677000}'),o={name:"features/ui-editor/components/note-list.md"};function n(h,t,i,l,s,b){return r(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="笔记列表组件-完整手册" tabindex="-1">笔记列表组件（完整手册） <a class="header-anchor" href="#笔记列表组件-完整手册" aria-label="Permalink to &quot;笔记列表组件（完整手册）&quot;">​</a></h1><p>路径：<strong>UI管理 → 页面配置 → 设计</strong> → 左侧 <strong>社区内容 → 笔记列表</strong></p><p>组件在编辑器中的名称是 <strong>笔记列表</strong>（<code>xiaoyi-note-list-section</code>）。它是首页、发现页、圈子页的 <strong>核心 Feed 组件</strong>，负责分页展示笔记/帖子，支持下拉加载、与 <strong>筛选标签</strong> 联动。</p><div class="warning custom-block"><p class="custom-block-title">互斥规则</p><p>同一页面 <strong>只能有一个</strong> 笔记列表、圈子列表或瀑布流，三选一。建议放在画布 <strong>最底部</strong>。</p></div><hr><h2 id="一、数据从哪来" tabindex="-1">一、数据从哪来 <a class="header-anchor" href="#一、数据从哪来" aria-label="Permalink to &quot;一、数据从哪来&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th>数据来源</th></tr></thead><tbody><tr><td><strong>编辑器画布</strong></td><td>演示笔记（可切换单图/多图/视频/音频预览）</td></tr><tr><td><strong>用户 App</strong></td><td>接口自动分页拉取，按区域、排序、筛选参数返回</td></tr></tbody></table><p>你在属性里改的是 <strong>卡片长什么样、显示哪些字段</strong>，不能手动增删线上某条笔记。</p><hr><h2 id="二、属性面板结构-15-个分组" tabindex="-1">二、属性面板结构（15 个分组） <a class="header-anchor" href="#二、属性面板结构-15-个分组" aria-label="Permalink to &quot;二、属性面板结构（15 个分组）&quot;">​</a></h2><p>选中笔记列表后，右侧 <strong>属性</strong> Tab 从上到下依次为：</p><table tabindex="0"><thead><tr><th>序号</th><th>分组名</th><th>作用</th></tr></thead><tbody><tr><td>①</td><td>预览示例</td><td>编辑器内看不同笔记类型效果</td></tr><tr><td>②</td><td>筛选联动</td><td>与筛选标签配合刷新列表</td></tr><tr><td>②b</td><td>视频笔记详情页</td><td>纯视频帖点击去向</td></tr><tr><td>③</td><td>整体布局</td><td>模板、正文宽度、封面尺寸</td></tr><tr><td>④</td><td>显示哪些内容</td><td>媒体/话题/正文/热评等开关</td></tr><tr><td>⑤</td><td>作者区</td><td>头像、昵称样式</td></tr><tr><td>⑥</td><td>昵称下方一行</td><td>时间 + 来自圈子胶囊</td></tr><tr><td>⑦</td><td>标题与正文</td><td>字号、颜色、行高</td></tr><tr><td>⑧</td><td>底栏互动区</td><td>赞/评/浏览文案与颜色</td></tr><tr><td>⑨</td><td>评论条外观</td><td>仅 <strong>模板 2</strong> 时显示</td></tr><tr><td>⑩</td><td>位置与圈子行</td><td>正文下方位置标签、圈子入口</td></tr><tr><td>⑪</td><td>音频笔记</td><td>音频帖播放区样式</td></tr><tr><td>⑫</td><td>图标（高级）</td><td>自定义赞/评/分享图标</td></tr><tr><td>⑬</td><td>用户标签</td><td>说明：标签样式在 <strong>自定义标签</strong> 菜单配</td></tr><tr><td>⑭</td><td>预览作者信息</td><td>仅编辑器演示用</td></tr><tr><td>⑮</td><td>点击卡片</td><td>整条笔记点击跳转</td></tr></tbody></table><p><strong>样式 Tab</strong>（与属性分离）见 <a href="#十样式-tab-分层说明">第十节</a>。</p><hr><h2 id="三、1-预览示例" tabindex="-1">三、① 预览示例 <a class="header-anchor" href="#三、1-预览示例" aria-label="Permalink to &quot;三、① 预览示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td><strong>单图</strong></td><td>画布塞一条单图笔记演示</td></tr><tr><td><strong>多图</strong></td><td>三张配图演示</td></tr><tr><td><strong>视频</strong></td><td>视频帖 + 封面演示</td></tr><tr><td><strong>音频</strong></td><td>音频帖 + 时长演示</td></tr><tr><td><strong>恢复默认</strong></td><td>回到编辑器默认示例</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>预览只改画布演示内容，<strong>不会</strong> 覆盖你已配好的颜色、字号等样式；也不会影响线上数据。</p></div><hr><h2 id="四、2-筛选联动-与筛选标签配合" tabindex="-1">四、② 筛选联动（与筛选标签配合） <a class="header-anchor" href="#四、2-筛选联动-与筛选标签配合" aria-label="Permalink to &quot;四、② 筛选联动（与筛选标签配合）&quot;">​</a></h2><h3 id="联动标识-filterlinkkey" tabindex="-1">联动标识 filterLinkKey <a class="header-anchor" href="#联动标识-filterlinkkey" aria-label="Permalink to &quot;联动标识 filterLinkKey&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><strong>联动标识</strong></td><td>须与上方 <strong>筛选标签</strong> 组件填 <strong>完全相同</strong> 的字符串</td><td><code>default</code></td></tr></tbody></table><p><strong>工作原理：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点击筛选标签某个 Tab</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>标签把该 Tab 的排序/圈子/话题等参数发给接口</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>下方 filterLinkKey 相同的笔记列表重新请求并刷新</span></span></code></pre></div><h3 id="配置步骤-必做-checklist" tabindex="-1">配置步骤（必做 checklist） <a class="header-anchor" href="#配置步骤-必做-checklist" aria-label="Permalink to &quot;配置步骤（必做 checklist）&quot;">​</a></h3><ul><li>[ ] 画布上方已添加 <strong>筛选标签</strong>（全页仅 1 个）</li><li>[ ] 筛选标签 <strong>内容模式</strong> = <strong>列表 API 联动</strong></li><li>[ ] 筛选标签 <strong>联动目标</strong> = <strong>笔记</strong></li><li>[ ] 筛选标签 <strong>联动标识</strong> = 例如 <code>home-feed</code></li><li>[ ] 笔记列表 <strong>联动标识</strong> = 同样填 <code>home-feed</code></li><li>[ ] 筛选标签每个 Tab 已配置 <strong>排序 order_by（笔记）</strong> 等参数</li></ul><h3 id="筛选标签侧常用参数-供-tab-配置参考" tabindex="-1">筛选标签侧常用参数（供 Tab 配置参考） <a class="header-anchor" href="#筛选标签侧常用参数-供-tab-配置参考" aria-label="Permalink to &quot;筛选标签侧常用参数（供 Tab 配置参考）&quot;">​</a></h3><p>在 <strong>筛选标签 → 选项</strong> 里，选中某个 Tab 后可配：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>可选值示例</th></tr></thead><tbody><tr><td>显示文字 label</td><td>Tab 上显示的名称</td><td>推荐、最新、视频</td></tr><tr><td>排序 order_by（笔记）</td><td>列表排序字段</td><td>智能热度、个性化推荐、创建、点赞、浏览、评论</td></tr><tr><td>排序方向</td><td>ASC / DESC</td><td>最新一般用 DESC</td></tr><tr><td>圈子 circle_id</td><td>只显示某圈子笔记</td><td>留空=不限制；可点 <strong>选择</strong></td></tr><tr><td>话题 topic_id</td><td>只显示某话题下笔记</td><td>留空=不限制</td></tr><tr><td>笔记类型 type</td><td>0 图文 / 1 视频 / 2 语音</td><td>视频 Tab 选 <code>1</code></td></tr><tr><td>闲置 idle_only</td><td>是否仅闲置帖</td><td>按需</td></tr><tr><td>排除置顶 exclude_pinned</td><td>是否排除置顶帖</td><td>「最新」Tab 可开</td></tr></tbody></table><p><strong>排序说明：</strong></p><table tabindex="0"><thead><tr><th>排序值</th><th>含义</th></tr></thead><tbody><tr><td>智能热度 smart</td><td>默认，综合热度算法</td></tr><tr><td>个性化推荐 recommend</td><td>需部署 Gorse；失败自动降级 smart</td></tr><tr><td>创建 created_at</td><td>按发布时间</td></tr><tr><td>点赞 like_count</td><td>按点赞数</td></tr><tr><td>浏览 view_count</td><td>按浏览量</td></tr></tbody></table><hr><h2 id="五、2b-视频笔记详情页" tabindex="-1">五、②b 视频笔记详情页 <a class="header-anchor" href="#五、2b-视频笔记详情页" aria-label="Permalink to &quot;五、②b 视频笔记详情页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>用户点击纯视频笔记后</th></tr></thead><tbody><tr><td><strong>平台详情页</strong></td><td>进入标准笔记详情页</td></tr><tr><td><strong>视频播放页</strong></td><td>进入沉浸式视频播放页（需功能开通）</td></tr></tbody></table><p>圈子页一般与首页保持一致。</p><hr><h2 id="六、3-整体布局" tabindex="-1">六、③ 整体布局 <a class="header-anchor" href="#六、3-整体布局" aria-label="Permalink to &quot;六、③ 整体布局&quot;">​</a></h2><h3 id="底栏样式-uitemplate-三选一" tabindex="-1">底栏样式 uiTemplate（三选一） <a class="header-anchor" href="#底栏样式-uitemplate-三选一" aria-label="Permalink to &quot;底栏样式 uiTemplate（三选一）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模板</th><th>名称</th><th>适用场景</th><th>底栏表现</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>传统双行</td><td>信息密度高、偏社区论坛</td><td>两行：互动数据 + 时间等</td></tr><tr><td><strong>2</strong></td><td>评论条</td><td>强调评论互动</td><td>底部假评论输入条（装饰）</td></tr><tr><td><strong>3</strong></td><td>简洁一行</td><td>清爽信息流（<strong>默认</strong>）</td><td>一行图标 + 数字</td></tr></tbody></table><h3 id="正文区域宽度-contentlayout" tabindex="-1">正文区域宽度 contentLayout <a class="header-anchor" href="#正文区域宽度-contentlayout" aria-label="Permalink to &quot;正文区域宽度 contentLayout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>效果</th></tr></thead><tbody><tr><td><strong>跟随底栏</strong></td><td>与作者区对齐（默认）</td></tr><tr><td><strong>与头像对齐</strong></td><td>正文左缘与头像对齐</td></tr><tr><td><strong>撑满整行</strong></td><td>正文占满卡片宽度</td></tr></tbody></table><h3 id="封面图边长-thumbsize" tabindex="-1">封面图边长 thumbSize <a class="header-anchor" href="#封面图边长-thumbsize" aria-label="Permalink to &quot;封面图边长 thumbSize&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>封面图边长</td><td><code>176</code> rpx</td><td>单图/视频封面正方形边长</td></tr></tbody></table><hr><h2 id="七、4-显示哪些内容-开关一览" tabindex="-1">七、④ 显示哪些内容（开关一览） <a class="header-anchor" href="#七、4-显示哪些内容-开关一览" aria-label="Permalink to &quot;七、④ 显示哪些内容（开关一览）&quot;">​</a></h2><p>点击 pill 切换开/关。<strong>关闭后对应区域不渲染</strong>，接口仍返回该字段。</p><table tabindex="0"><thead><tr><th>开关</th><th>属性</th><th>关闭后</th></tr></thead><tbody><tr><td>图片视频</td><td>showCover</td><td>不显示封面/视频/多图</td></tr><tr><td>话题标签</td><td>hideTopic=true</td><td>不显示 #话题</td></tr><tr><td>正文摘要</td><td>hideContent=true</td><td>不显示正文文字</td></tr><tr><td>热评预览</td><td>hideHotComment=true</td><td>不显示热评条</td></tr><tr><td>昵称下行</td><td>authorSublineTimeCircle</td><td>不显示「日期 | 来自 · 圈子」行</td></tr><tr><td>认证标签</td><td>hideAuthorMetaRow=true</td><td>不显示认证/类型等标签行</td></tr><tr><td>位置圈子</td><td>hideLocationCircleRow=true</td><td>不显示位置+圈子行</td></tr><tr><td>底栏时间</td><td>hideFooterTime=true</td><td>底栏不显示时间</td></tr></tbody></table><h3 id="多图展示方式" tabindex="-1">多图展示方式 <a class="header-anchor" href="#多图展示方式" aria-label="Permalink to &quot;多图展示方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>开关</th><th>说明</th></tr></thead><tbody><tr><td><strong>多图横滑</strong> multiImageScroll</td><td>多图横向滑动展示</td></tr><tr><td><strong>拼图样式</strong> imageCollageTemplate</td><td>九宫格/拼图布局</td></tr></tbody></table><hr><h2 id="八、5-8-样式类属性-属性-tab-内" tabindex="-1">八、⑤～⑧ 样式类属性（属性 Tab 内） <a class="header-anchor" href="#八、5-8-样式类属性-属性-tab-内" aria-label="Permalink to &quot;八、⑤～⑧ 样式类属性（属性 Tab 内）&quot;">​</a></h2><h3 id="作者区" tabindex="-1">作者区 <a class="header-anchor" href="#作者区" aria-label="Permalink to &quot;作者区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认参考</th><th>说明</th></tr></thead><tbody><tr><td>头像大小 avatarSize</td><td>68 rpx</td><td>作者头像边长</td></tr><tr><td>头像圆角 avatarRadius</td><td>圆形</td><td>填大值=圆角矩形</td></tr><tr><td>昵称字号 nicknameFontSize</td><td>26 rpx</td><td>—</td></tr><tr><td>昵称字重 nicknameFontWeight</td><td>700</td><td>—</td></tr><tr><td>昵称颜色 nicknameColor</td><td>—</td><td>留空用主题默认</td></tr></tbody></table><h3 id="昵称下方一行-开启「昵称下行」后" tabindex="-1">昵称下方一行（开启「昵称下行」后） <a class="header-anchor" href="#昵称下方一行-开启「昵称下行」后" aria-label="Permalink to &quot;昵称下方一行（开启「昵称下行」后）&quot;">​</a></h3><p>显示类似：<code>07-21 | 来自 · 武汉大学 ›</code></p><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>文字字号 authorSublineFontSize</td><td>18 rpx</td><td>—</td></tr><tr><td>与昵称间距 authorSublineMarginTop</td><td>6 rpx</td><td>—</td></tr><tr><td>文字颜色 authorSublineColor</td><td>—</td><td>—</td></tr><tr><td>元素间距 authorSublineRowGap</td><td>4 rpx</td><td>日期与胶囊间距</td></tr><tr><td>圈子头像 authorSublineCircleLogoSize</td><td>22 rpx</td><td>胶囊内小 logo</td></tr><tr><td>圈子名字号/颜色/字重</td><td>18 rpx 等</td><td>—</td></tr><tr><td>箭头大小 authorSublineArrowSize</td><td>16 px</td><td>—</td></tr><tr><td>胶囊内间距/内边距</td><td>6 / <code>2rpx 8rpx 2rpx 6rpx</code></td><td>—</td></tr></tbody></table><h3 id="标题与正文" tabindex="-1">标题与正文 <a class="header-anchor" href="#标题与正文" aria-label="Permalink to &quot;标题与正文&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>标题字号 titleFontSize</td><td>30 rpx</td><td>—</td></tr><tr><td>标题字重 titleFontWeight</td><td>600</td><td>—</td></tr><tr><td>标题颜色 titleColor</td><td>#111111</td><td>—</td></tr><tr><td>标题行高 titleLineHeight</td><td>1.4 或 40rpx</td><td>—</td></tr><tr><td>正文字号 contentFontSize</td><td>26 rpx</td><td>—</td></tr><tr><td>正文颜色 contentColor</td><td>#333333</td><td>—</td></tr><tr><td>正文行高 contentLineHeight</td><td>36rpx 或 1.5</td><td>—</td></tr><tr><td>次要文字颜色 mutedColor</td><td>#999999</td><td>时间、位置等灰色小字</td></tr></tbody></table><h3 id="底栏互动区" tabindex="-1">底栏互动区 <a class="header-anchor" href="#底栏互动区" aria-label="Permalink to &quot;底栏互动区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>赞旁文字 likeLabel</td><td>赞</td><td>—</td></tr><tr><td>评旁文字 commentLabel</td><td>评</td><td>—</td></tr><tr><td>浏览前缀 browseLabel</td><td>浏览</td><td>—</td></tr><tr><td>数字旁短字 viewLabel</td><td>览</td><td>显示为「浏览 1.2k 览」类格式</td></tr><tr><td>图标默认色 actionIconColor</td><td>—</td><td>未点赞态</td></tr><tr><td>已赞颜色 actionLikeActiveColor</td><td>—</td><td>点赞后图标色</td></tr><tr><td>数字文字色 actionTextFontSize</td><td>18 rpx</td><td>—</td></tr><tr><td>浏览数颜色 viewCountColor</td><td>—</td><td>—</td></tr></tbody></table><hr><h2 id="九、9-评论条外观-仅模板-2" tabindex="-1">九、⑨ 评论条外观（仅模板 2） <a class="header-anchor" href="#九、9-评论条外观-仅模板-2" aria-label="Permalink to &quot;九、⑨ 评论条外观（仅模板 2）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>占位提示 commentPlaceholder</td><td>如 <code>写评论...</code></td></tr><tr><td>左侧小头像 miniAvatarSize</td><td>默认 48 rpx</td></tr><tr><td>占位字号/颜色</td><td>—</td></tr><tr><td>输入框背景色/圆角/内边距</td><td>灰底圆角条</td></tr><tr><td>前置图标 / emoji</td><td>✨ 等</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>评论条 <strong>仅装饰</strong>，用户点击会进详情页评论，不能在此直接发文。</p></div><hr><h2 id="十、样式-tab-分层说明" tabindex="-1">十、样式 Tab 分层说明 <a class="header-anchor" href="#十、样式-tab-分层说明" aria-label="Permalink to &quot;十、样式 Tab 分层说明&quot;">​</a></h2><p>笔记列表的 <strong>样式</strong> 与 <strong>属性</strong> 分工：</p><table tabindex="0"><thead><tr><th>样式 Tab 分组</th><th>作用对象</th></tr></thead><tbody><tr><td><strong>尺寸、外边距</strong></td><td>整个列表区域（section 外壳）</td></tr><tr><td><strong>内边距、背景、圆角、边框</strong></td><td>每一条 <strong>卡片内部</strong> 的外壳</td></tr><tr><td><strong>属性 Tab</strong></td><td>卡片里文字、图标、开关</td></tr></tbody></table><p><strong>推荐调法：</strong></p><ol><li>列表与上方模块间距 → 样式 <strong>marginTop</strong> 20～30</li><li>卡片白底圆角 → 样式 <strong>背景 #FFF</strong>、<strong>圆角 16</strong>、<strong>内边距 24</strong></li><li>标题字号 → 属性 <strong>标题字号</strong> 30，不是样式 Tab</li></ol><hr><h2 id="十一、15-点击卡片" tabindex="-1">十一、⑮ 点击卡片 <a class="header-anchor" href="#十一、15-点击卡片" aria-label="Permalink to &quot;十一、⑮ 点击卡片&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td><strong>点击后执行</strong> clickAction</td><td>整条笔记点击跳转</td></tr></tbody></table><p><strong>默认行为：</strong> 留空时进入 <strong>笔记详情页</strong>。</p><p>可改为：跳转自定义页、预览图片等（一般用默认即可）。</p><hr><h2 id="十二、三套推荐配置方案" tabindex="-1">十二、三套推荐配置方案 <a class="header-anchor" href="#十二、三套推荐配置方案" aria-label="Permalink to &quot;十二、三套推荐配置方案&quot;">​</a></h2><h3 id="方案-a-标准校园首页-推荐" tabindex="-1">方案 A：标准校园首页（推荐） <a class="header-anchor" href="#方案-a-标准校园首页-推荐" aria-label="Permalink to &quot;方案 A：标准校园首页（推荐）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>uiTemplate</td><td>3 简洁一行</td></tr><tr><td>联动 Key</td><td><code>home-feed</code> + 筛选标签三 Tab（推荐/最新/视频）</td></tr><tr><td>显示</td><td>媒体、话题、正文、热评、位置圈子 全开</td></tr><tr><td>样式</td><td>卡片 marginTop 16，卡片背景 #FFF，圆角 16</td></tr></tbody></table><h3 id="方案-b-轻量瀑布信息流" tabindex="-1">方案 B：轻量瀑布信息流 <a class="header-anchor" href="#方案-b-轻量瀑布信息流" aria-label="Permalink to &quot;方案 B：轻量瀑布信息流&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>uiTemplate</td><td>3</td></tr><tr><td>hideHotComment</td><td>开（关热评）</td></tr><tr><td>hideFooterTime</td><td>开</td></tr><tr><td>thumbSize</td><td>200</td></tr></tbody></table><h3 id="方案-c-重互动社区" tabindex="-1">方案 C：重互动社区 <a class="header-anchor" href="#方案-c-重互动社区" aria-label="Permalink to &quot;方案 C：重互动社区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>uiTemplate</td><td>2 评论条</td></tr><tr><td>评论条占位</td><td><code>说点什么...</code></td></tr><tr><td>热评</td><td>开</td></tr></tbody></table><hr><h2 id="十三、保存与验收" tabindex="-1">十三、保存与验收 <a class="header-anchor" href="#十三、保存与验收" aria-label="Permalink to &quot;十三、保存与验收&quot;">​</a></h2><ol><li><strong>保存</strong> 页面 → 列表 <strong>启用</strong></li><li>App 切到对应 <strong>区域</strong></li><li>验收：</li></ol><table tabindex="0"><thead><tr><th>检查</th><th>预期</th></tr></thead><tbody><tr><td>首屏加载</td><td>出现笔记卡片</td></tr><tr><td>上拉</td><td>加载更多，底部「没有更多了」</td></tr><tr><td>切换筛选 Tab</td><td>列表内容/排序变化</td></tr><tr><td>点击笔记</td><td>进详情</td></tr><tr><td>点赞</td><td>图标变已赞色</td></tr></tbody></table><hr><h2 id="十四、常见问题" tabindex="-1">十四、常见问题 <a class="header-anchor" href="#十四、常见问题" aria-label="Permalink to &quot;十四、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>切换 Tab 列表不变</td><td>联动 Key 不一致</td><td>标签与列表填相同标识</td></tr><tr><td>列表空白</td><td>区域无笔记 / 筛选过严</td><td>发测试帖；检查 circle_id、topic_id</td></tr><tr><td>改了样式线上没变</td><td>未启用 / 区域不对</td><td>启用配置；核对区域</td></tr><tr><td>推荐排序无效</td><td>Gorse 未部署</td><td>换「智能热度」或部署推荐服务</td></tr><tr><td>视频帖点击不对</td><td>视频详情页选项</td><td>检查「平台详情页/视频播放页」</td></tr><tr><td>认证标签样式不对</td><td>在笔记列表改不了</td><td>去 <strong>UI管理 → 自定义标签</strong></td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/ui-editor/components-layout#筛选标签">筛选标签</a></li><li><a href="/features/ui-editor/scenarios/homepage">从零搭建首页</a></li><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a></li><li><a href="/features/circle-note">圈子与笔记业务配置</a></li></ul>`,92)])])}const u=d(o,[["render",n]]);export{g as __pageData,u as default};
